-- 2405 🏋️ Exercises from the book "coach-your-team-to-score-more-goals-data-driven-analysis-of-europe-s-elite-used-" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coach-your-team-to-score-more-goals-data-driven-analysis-of-europe-s-elite-used-');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Unopposed corner routines with signals', 'set_piece', 'unopposed', 'set_piece', 24, 24, 'Session 1: Practice 1', NULL, 'Rehearse corner deliveries, coded signals and attacking runs so every scoring zone is covered.', 'Corner on a half pitch with 5 mannequins in the box standing in for defenders, a GK in goal, and the full attacking team with box runners plus outside players waiting for second balls.', 'The squad first agrees 5 corner types, each with its own signal given by the taker. Each signal is either a direct corner or a short corner and cross, delivered to the near post, far post or penalty spot while runners attack their areas.', 'No live defenders; the aim is to learn the deliveries, the runs and the signals.', 'Practise corners from both the left and the right.', 'Runs cover all potential scoring areas; outside players sit ready for second balls.', '10 attackers + GK', 11, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 10),
  ('Corners 10v7 with counter-attack gates', 'set_piece', 'opposed', 'set_piece', 25, 25, 'Session 1: Practice 2', NULL, 'Score from rehearsed corners against live defenders and stay ready for clearances and counters.', 'Half pitch: 10 attackers v 7 defenders + GK in place of the mannequins. Near halfway there are two wide pole gates and one middle pole gate for the defenders to counter into.', 'The attackers use any corner routine from the previous practice to try to score. Box runners make the same runs, and outside players pick up second balls to keep the attack going. If the defenders win the ball, they counter fast towards the gates.', 'Defenders score 2 for dribbling through a wide gate and 3 for the middle gate.', NULL, 'Outside players must be ready for second balls from clearances.', '10v7+GK', 18, 18, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Unopposed short corner variations', 'set_piece', 'unopposed', 'set_piece', 26, 26, 'Session 1: Practice 3', NULL, 'Learn short-corner routines and their signals before the cross into the box.', 'Same as Practice 1: corner set-up with mannequins as defenders, a GK, box runners, outside players, and a full back and link player near the corner.', 'Each of 5 signals calls a different short routine. For example, the taker plays a one-two and then crosses; or he passes short to the full back, who crosses; or the ball reaches the full back through a link player. The crosser aims at the near post, far post or penalty spot.', 'No active defenders.', 'Practise from both sides.', 'Runs cover all scoring areas; outside players are ready for second balls.', '10 attackers + GK', 11, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Short corners 10v7 with counter gates', 'set_piece', 'opposed', 'set_piece', 27, 27, 'Session 1: Practice 4', NULL, 'Score from short-corner routines against live defenders and stay ready for counters.', 'Half pitch: 10 attackers v 7 defenders + GK, with two wide pole gates and one middle pole gate near halfway.', 'The attackers run any of the short-corner routines they have rehearsed and try to score, keeping the attack alive from second balls. If the defenders win the ball, they counter towards the gates.', 'Defenders score 2 through a wide gate and 3 through the middle gate.', NULL, 'Outside players must be ready for clearances.', '10v7+GK', 18, 18, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('3v1 wide, overlap and cut back', 'combination', 'overload', 'in_possession', 34, 34, 'Session 2: Practice 1', NULL, 'Create a wide overload, release the overlapping full back and cut the ball back to arriving runners.', 'Half pitch with a marked wide area on each flank, each holding a 3v1. The high corner areas are marked out, there is a GK in goal, and the coach waits with balls at the centre circle.', 'The coach passes to the full back, who enters the wide area to make 3v1. The three combine and then send the overlapping full back into the high corner area. The other two attack the near and far posts, and the full back cuts the ball back for either of them to score.', NULL, 'Alternate sides; the next group starts on the other flank.', 'Time the overlap; split the runs to near and far post.', '3v1 per side + GK', 9, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 50),
  ('Winger 1v1 then cut back to runners', 'combination', 'opposed', 'in_possession', 35, 35, 'Session 2: Practice 2', NULL, 'Win a wide 1v1 and cut back for a forward and a midfielder attacking the posts.', 'Half pitch with a corner area marked on each wing, a mannequin and a red defender by each corner area, a GK, and the coach with balls at the centre circle. Midfielder, forward and winger groups wait.', 'The coach passes to the midfielder, who plays the winger in out wide. The defender runs round the mannequin to defend the corner area. The winger takes him on in a 1v1 and cuts the ball back for the forward or the midfielder, who run to the near and far post.', NULL, 'Players return or rotate positions; alternate flanks.', 'Runners time their arrival to meet the cut back.', '3 attackers v 1 defender + GK per phase', 9, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 60),
  ('High 1v1 on flank, cut back to edge', 'combination', 'opposed', 'in_possession', 36, 36, 'Session 2: Practice 3', NULL, 'Beat a defender high on the flank and cut back to a teammate arriving at the edge of the box.', 'Half pitch with marked corner areas, mannequins, a defender on each side, a GK, and midfielder, full back, winger and forward groups.', 'The midfielder passes to the full back, who finds the winger in the corner area. The defender closes him down on his first touch to make 1v1. The winger beats him and cuts the ball back to the edge of the box, where the forward and midfielder have moved to offer two options either side of the cones.', NULL, 'Alternate sides.', 'The crosser looks up before the cut back and picks the right player at the right speed.', '4 attackers v 1 + GK per phase', 10, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('6v6+2 four-corner-area cut back game', 'small_sided_game', 'overload', 'in_possession', 37, 37, 'Session 2: Practice 4', NULL, 'Score goals that come from cut backs out of the wide corner areas.', 'Half pitch with a full-size goal and GK at each end and four corner areas marked. 6v6 plus 2 jokers who play for the team in possession; a third team rests outside.', 'Play starts from a GK. Teams try to get the ball into a corner area so the final pass can come from there. After a goal, the GK of the team that conceded restarts.', 'A goal counts only if the final pass comes from a corner area. Defenders may not enter the corner areas and can only intercept passes into them. Games last 5-7 minutes, then teams and jokers rotate; most goals over a set number of games wins.', NULL, NULL, '6v6+2 + GKs, third team resting', 16, 22, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('4v4 in circle, through pass 1v1', 'possession', 'opposed', 'in_possession', 42, 42, 'Session 3: Practice 1', NULL, 'Keep the ball under pressure, then play a through pass for a forward to finish 1v1 against the GK.', '4v4 inside the centre circle, with each team''s forward waiting on the halfway line outside it. A GK is in the goal and two more teams wait to rotate in.', 'The coach serves to one team, which needs 3 passes before it can play a through pass to its forward. The forward sprints onto it to score while the other team''s outside player chases back to defend. If the opponents win the ball, they need their own 3 passes and then a through pass.', '3 passes before the through ball; if the ball leaves the circle, the coach serves the other team. Forwards change every rep.', 'Run it as a 4-team competition, adding up the goals.', NULL, '4v4 + 2 forwards + GK, 4 teams rotating', 11, 21, 'Centre circle + half pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('5(+1)v4 midfield zone, through pass', 'passing_opposed', 'overload', 'in_possession', 43, 43, 'Session 3: Practice 2', NULL, 'Find time and a passing lane in a crowded midfield to release a forward in behind.', 'Central zone marked across the pitch in midfield: 5 blue players and 1 yellow forward v 4 red defenders. 3 mannequins act as defenders before the goal, with a GK. Yellow forwards queue outside with balls.', 'A yellow player outside serves into the zone. The blues pass to find a player with time and a lane, then play a through pass. The yellow forward times his run beyond the mannequins and finishes against the GK. The reds press to block the through pass.', 'After each action, 2 defenders rotate out to recover; the forward changes and the next yellow serves.', NULL, 'The through pass must be seen early and played accurately; the forward times his run in behind.', '5(+1)v4 + GK', 11, NULL, 'Midfield zone (half pitch)', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('4v4+2 build-up, through pass to half', 'small_sided_game', 'overload', 'in_possession', 44, 44, 'Session 3: Practice 3', NULL, 'Build up in your own half and play a through pass for a runner to finish.', 'Pitch split into two halves with a goal and GK at each end. 4v4 plus 2 jokers start in the attacking team''s own half, and a third team waits.', 'The blue GK starts. The blues need at least 3 passes, then a through pass into the attacking half for a runner to finish 1v1 against the GK. Then the reds attack from their own GK the same way.', '3 passes before the through ball. Defenders may not enter the attacking half, so the finish is a pure 1v1. If the reds win the ball, they need 3 passes before trying to score.', 'Teams rotate; run it as a 3-team competition.', NULL, '4v4+2 + GKs, 3 teams', 16, 20, NULL, NULL, NULL, NULL, true, true, true, NULL, 110),
  ('7v7 build-up and through pass game', 'small_sided_game', 'opposed', 'in_possession', 45, 45, 'Session 3: Practice 4', NULL, 'Play through the opponents'' lines in build-up and release a runner in behind to finish.', 'Half pitch with two goals and GKs. 7v7 in 4-3 shapes starts in the low area, with a third team resting outside.', 'The attackers build up from their GK while the defenders press high. The back line either plays into the 3 midfielders for a through pass in behind or goes direct with a long through ball into the attacking half. The runner finishes 1v1 against the GK unopposed. The defenders score if they win the ball.', 'Teams switch ends after each phase. 5-7 minute games with 3 teams rotating; most goals over a set number of games wins.', NULL, NULL, '7v7 + GKs, third team resting', 16, 23, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 120),
  ('Double one-two into side of box', 'combination', 'unopposed', 'in_possession', 52, 52, 'Session 4: Practice 1', NULL, 'Reach the side of the box with combination play and cut back for a finish.', 'Full pitch split into 4 sections, groups of 6 working in pairs with mannequins and two cones near the box, and a GK.', 'A passes to B, who carries inside. A runs past the mannequin for B''s return pass, gives it back inside, then sprints for a through pass into the side of the box. B runs through the two cones into the box and finishes A''s cut back.', NULL, NULL, 'All groups work at once; the next pair goes as soon as the action ends.', 'Groups of 6 in pairs + GK', 7, NULL, 'Full pitch in 4 sections', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Wide combination into side of box 2v2', 'combination', 'opposed', 'in_possession', 53, 55, 'Session 4: Practice 2 (2a-2c)', NULL, 'Combine wide to get into the side of the box, then cut back or cross low against 2 defenders.', 'Half pitch with mannequins, a GK and 2 red defenders in the box. Five attackers: right back, two midfielders, winger and forward.', '2a: The RB passes to M1, who finds M2, who sets wide to the RB. The RB plays the winger in behind or to feet, and the winger dribbles past a mannequin into the side of the box. He then cuts back to M2 or the forward, or crosses low across the box, while 2 defenders try to block or intercept.', 'After each phase, repeat from the left; 2 new defenders rotate in and attackers rotate roles.', '2b: The RB plays a one-two with M1, then sends M2 through into the side of the box; the winger and forward attack the box. 2c: The RB plays to M1, M1 to M2, and M2 to the forward, who releases the winger''s third-man run off the flank into the side of the box for a cut back or low cross.', 'Choose between playing to feet and playing into space.', '5v2 + GK', 8, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Third-man run, side-of-box cut back 2v2', 'combination', 'opposed', 'in_possession', 55, 55, 'Session 4: Practice 2c', NULL, 'Use a third-man run to get the winger into the side of the box and assist with a cut back or low cross.', 'Half pitch with the side-of-box zones marked; mannequins as opponents in midfield, a GK, 2 red defenders in the box against 2 blue attackers (M2 and forward); RB, M1, M2, F and W start in their positions with ball supply at the halfway line.', 'RB plays inside to M1, who plays forward to M2; M2 finds the forward, who slips a pass into the side of the box for the winger''s run from the flank. The winger then cuts back or plays a low cross for M2 or the forward to finish, while 2 defenders try to block or intercept.', NULL, 'Repeat from the left side with 2 fresh defenders; players rotate through all roles.', 'Time the winger''s run into the side of the box; look up before the final ball and pick near post or front of goal.', '5 attackers + 2 defenders + GK (2v2 in box)', 8, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 150),
  ('6v6+2 SSG, assists from side of box', 'small_sided_game', 'overload', 'in_possession', 56, 56, 'Session 4: Practice 3', NULL, 'Build attacks that end with an assist played from the side-of-box areas.', 'Half pitch of reduced width with a full goal and GK at each end; side-of-box zones highlighted at both ends; two teams of 6 plus 2 Jokers who join the team with the ball; a third team rests outside.', 'Play starts from a GK and the team builds up with the Jokers'' help to score. After each goal the restart comes from the GK of the team that conceded.', 'A goal only counts if the assist comes from inside a side-of-box zone. Games of 5-8 minutes; teams rotate after each game, and if no goal is scored in a set time the outside team swaps in. Most goals over a set number of games wins.', NULL, 'Get the ball into the side of the box quickly and look for the cut back.', '6v6+2 + GKs, third team resting', 16, 22, 'Half pitch, reduced width', NULL, NULL, NULL, true, true, true, NULL, 160),
  ('One-two wide, deep cross from low zone', 'finishing', 'unopposed', 'in_possession', 63, 63, 'Session 5: Practice 1', NULL, 'Practise getting the winger free in the low wide zone and delivering a deep cross for two forwards to finish.', 'Full pitch split into 4 sections with groups of 4 starting in each, mannequins as defenders, 4 forwards at each end and a GK in goal; low wide zone marked on the flank.', 'A midfielder passes to the winger, who plays a one-two with him and receives in the low wide zone. The winger crosses deep into the box where 2 forwards make opposite near/far post runs; one controls and shoots.', NULL, 'Winger moves to the other side of the pitch to join that group so crosses are practised from both flanks; midfielder becomes the winger.', 'Forwards split near and far post; quality and depth of the cross.', 'Groups of 4 + 4 forwards each end + GKs', 10, NULL, 'Full pitch in 4 sections', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('One-two, winger dribbles high, cross and finish', 'finishing', 'unopposed', 'in_possession', 64, 64, 'Session 5: Practice 2', NULL, 'Work the ball to the winger who drives into the high wide zone and crosses for the forward.', 'As Practice 1 but with 3 players in the wide area (full back, midfielder, winger), mannequins as defenders, forwards and GK at goal; high wide zone marked near the by-line.', 'Midfielder plays to the full back, who returns it to complete the one-two. The midfielder steps forward and passes to the winger dropping off; the winger dribbles into the high wide zone, finds the forward and crosses.', NULL, 'Winger moves to the other side''s group so both flanks are trained; midfielder becomes full back, full back becomes winger.', 'Forward chooses one of 3 positions (near, far, centre) to attack; winger looks up to locate him before crossing.', 'Groups of 3 in wide areas + forwards + GKs', 8, NULL, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('6v6+4 SSG, diagonal goals, wide zones', 'small_sided_game', 'overload', 'in_possession', 65, 65, 'Session 5: Practice 3', NULL, 'Create assists from low and high wide zones, including deciding when to release the full back.', '7 zones marked out (size to suit age/level), with 2 mobile goals placed diagonally opposite each other and GKs; a yellow Joker in each of the 4 wide zones playing for the team with the ball; a third team waits outside.', '6v6 plus the 4 wide Jokers starting from the GK. Blue attackers can move across zones but red defenders cannot; play is worked out to the wide zones for the final ball.', 'The assist must come from a low or high wide zone; reds have the same aim if they win the ball. 5-minute games then the waiting team rotates in; total score decides the winner.', 'First half goals set up for right-sided assists by right backs; second half move goals to the left (still diagonally opposite) for left backs.', 'Central midfielder''s choice depends on how the defender positions himself.', '6v6+4 + GKs, third team waiting', 18, 24, 'Depends on age/level', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('7v7 SSG, assists from wide zones', 'small_sided_game', 'opposed', 'in_possession', 66, 66, 'Session 5: Practice 4', NULL, 'Score from crosses and passes delivered from the wide zones in a real game.', '7v7 plus GKs with 2 wide zones marked down each flank; a third team waits outside.', 'Game starts from the GK; the attacking team works the ball wide and the last pass must come from a wide zone. After a goal, restart from the GK of the team that conceded, who plays out quickly.', 'Assist must come from a wide zone; only 1 attacker may enter a wide zone at a time and no defenders may enter; unlimited touches in wide zones. Reds have the same aim on winning the ball. 5-minute games, waiting team rotates in and starts in attack from its GK.', NULL, 'GK restarts fast to speed up the game.', '7v7 + GKs, third team waiting', 16, 23, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Turn in centre space, through pass, finish', 'combination', 'unopposed', 'in_possession', 71, 71, 'Session 6: Practice 1', NULL, 'Receive and turn in the centre space, then thread a through pass for a run in behind to finish.', 'Two groups, one in each half; 2 mannequins at the edge of the box, players A, B1, B2 and C in a central channel, a GK in goal.', 'A passes to B1 or B2, who receives and turns either way off his cone. He plays a through pass (either side of or between the mannequins) for C, who starts between the mannequins and times his run, then receives in the box and shoots.', NULL, NULL, 'C makes eye contact and runs at the right moment to show where he wants the ball; B decides which way to turn.', 'Groups of 5+ per half + GK', 5, NULL, 'Half pitch central channel', NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Centre space passing options, through pass', 'combination', 'unopposed', 'in_possession', 72, 72, 'Session 6: Practice 2', NULL, 'Choose between several receivers in the centre space, turn and play the through pass for a finish.', 'Two groups, one in each half; starters A1/A2 out wide, B in the centre, C1, C2, C3 spread across the centre space, D the forward between 2 mannequins, GK in goal.', 'A1 or A2 passes inside to B, who chooses C1, C2 or C3. The receiver turns and plays a through pass for D''s run in behind; D finishes past the GK.', NULL, NULL, 'D times his run and makes eye contact to signal the pass; through pass can go either side of or between the mannequins.', 'Groups of 7+ + GK', 7, NULL, 'Half pitch central area', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('4v2 in centre space then 2v1 finish', 'phase_of_play', 'overload', 'in_possession', 73, 73, 'Session 6: Practice 3', NULL, 'Play through a crowded centre space and feed the forwards for a 2v1 finish.', 'Centre space highlighted with 4 blues v 2 reds; in the box 2 yellow forwards v 1 red defender and a GK; outside yellow servers on each side with balls; resting players outside.', 'An outside yellow passes into a blue in the centre space; the blues find a free player who passes forward to a yellow in the box. The 2 forwards play 2v1 to score.', 'Restart from the opposite outside yellow; box defender rotates out and a resting player enters; rotate team roles after a set number of repetitions.', NULL, 'Find the free man quickly and pass forward early.', '4v2 + 2v1 + GK + servers', 12, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('6v6+2 narrow game, centre space assist', 'small_sided_game', 'overload', 'in_possession', 74, 74, 'Session 6: Practice 4', NULL, 'Build up through the centre and play the final pass from the centre space into the box for the forward.', 'Full-length pitch at the width of the box; 6v6 + 2 yellow Jokers + GKs; both penalty boxes are end zones with no offside; third team rests outside.', 'GK starts by passing into the centre space; the attacking team builds up and moves the ball into the end zone for its forward to score.', 'Final pass must be played from within the centre space; only 1 blue and 1 red may enter the end zone once the pass is struck. Games of 3-5 minutes, teams rotate, most goals over a set number of games wins; after each goal the GK of the team that conceded restarts in attack.', NULL, NULL, '6v6+2 + GKs, third team resting', 16, 22, 'Full length, width of the box', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Long switch to half space, final ball', 'combination', 'unopposed', 'in_possession', 79, 79, 'Session 7: Practice 1', NULL, 'Receive in the half space and deliver an accurate assist into the box.', 'Half spaces marked on both sides of the pitch; A starts in one half space, B in the opposite one, forward C in the box, 2 mannequins and a GK.', 'A plays a long pass across to B in the opposite half space; B controls and quickly plays an accurate final pass into the box, aerial or along the ground. C controls and tries to score.', NULL, 'Repeat starting with A2''s pass to B2 from the other side; two groups can work in each half.', 'Precision on the long passes and on the final ball.', 'Groups of 3+ + GK', 4, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Inside then half space, through pass', 'combination', 'unopposed', 'in_possession', 80, 80, 'Session 7: Practice 2', NULL, 'Move the ball inside and then into the half space for a through pass into the box.', 'Half spaces marked; A out wide, B in the centre, C in the half space, forward D near 2 mannequins at the box edge, GK in goal.', 'A plays diagonally to B in the centre; B passes to C in the half space, who plays a through pass for D''s run between the mannequins into the box; D controls and shoots.', NULL, 'Repeat from the other side starting with A2 to B2; two groups can work in each half.', NULL, 'Groups of 4+ + GK', 5, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 260),
  ('4v4+2 SSG, assists from half spaces', 'small_sided_game', 'overload', 'in_possession', 81, 81, 'Session 7: Practice 3', NULL, 'Score with an assist played from one of the half spaces.', 'Half pitch at the width of the box; the box is the end zone and the 2 half spaces are marked; 4v4 + 2 yellow Jokers + GK; two more teams wait outside.', 'Coach starts the game; the team in possession, helped by the Jokers, tries to score with an assist from a half space. After the phase the blues rotate out for the whites, and the coach restarts with a pass to the reds who now attack.', 'Assist must come from a half space; only 1 blue and 1 red may enter the box once the pass is played. Goals added up; most total goals wins. Jokers can be a team so all 4 teams rotate.', NULL, NULL, '4v4+2 + GK, teams rotating', 11, 19, 'Half pitch, width of the box', NULL, NULL, NULL, true, true, true, NULL, 270),
  ('8v8 game, assists from half spaces', 'conditioned_game', 'opposed', 'in_possession', 82, 82, 'Session 7: Practice 4', NULL, 'Build up and play the final pass from a half space in a bigger game.', 'Full-length pitch at the width of the box with both penalty boxes as end zones (no offside); half spaces marked; 8v8 + GKs; a third team rests outside.', 'GK passes out and the attackers build up to get the ball into the end zone for a goal; reds try to win it and score the same way.', 'Final pass must come from a half space; players may enter the end zone only once the pass into it is struck. Games of 3-5 minutes, teams rotate, most goals over a set number of games wins.', NULL, NULL, '8v8 + GKs, third team resting', 18, 26, 'Full length, width of the box', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('3+1v1 possession then 2v1 in front of box', 'phase_of_play', 'overload', 'in_possession', 91, 91, 'Session 8A: Practice 1', NULL, 'Keep the ball in midfield then play into the front centre of the box for a 2v1 finish.', 'A midfield zone with 3 blues + an outside blue v 1 red; in front of goal a front-centre-of-box zone with 2 blue forwards v 1 red defender and a GK; spare defenders rest outside.', 'Outside blue starts it; the blues make 3 passes in the first zone, then pass forward into the box zone. The 2 forwards find space, control and shoot, or pass to the partner if the defender closes them down.', '3+ passes before the forward pass. Red defenders rotate with resting players after each repetition; change defenders after a set time.', NULL, 'Forwards move to find free space to receive; use the partner when closed down.', '3(+1)v1 + 2v1 + GK', 9, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('4v1 possession, pass wide, 1v1 in box', 'phase_of_play', 'overload', 'in_possession', 92, 92, 'Session 8A: Practice 2', NULL, 'Keep possession centrally, then go wide or direct to feed the forward for a 1v1 in the front centre of the box.', 'First zone 4 blues v 1 red; front-centre-of-box zone with 1 blue forward v 1 red defender and GK; wide blue players on each side outside the zones.', 'Blues make 3 passes, then play to the forward or to a wide player. Wide players pass or dribble into the box zone to feed the forward, who plays 1v1 to score; if no shot is on he can play back out to a wide player and continue.', '3+ passes before playing forward; if the direct pass is blocked, play wide. Defenders rotate with resting players; blues rotate roles.', NULL, 'Forward looks for a shooting chance first, recycles wide if none.', '4v1 + 1v1 + wide players + GK', 10, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Multi-zone 4v4+3 SSG, wide crossing zones', 'small_sided_game', 'overload', 'in_possession', 93, 93, 'Session 8A: Practice 3', NULL, 'Feed the forward in the front centre of the box from central play or crosses from wide.', 'Defensive-half central zone with 3 blues + 1 Joker v 3 reds, two wide crossing zones each with a yellow Joker, front-centre-of-box zone with 1v1 plus GK, goals at both ends; third team resting outside.', 'GK starts a 3(+1)v3 in the central zone; blues make 3 passes then play to their forward or a wide Joker, who crosses or passes into the box zone. Forward plays 1v1 to score or plays back out wide. Reds who win it do the same toward the other goal.', '3+ passes before playing forward; only the wide Jokers may enter the crossing zones. Games of 3-5 minutes, teams rotate, most goals over a set number of games wins.', NULL, NULL, '4v4+3 + GKs, third team resting', 13, 19, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('7v7 SSG, front-box goals, switch direction', 'small_sided_game', 'opposed', 'in_possession', 94, 94, 'Session 8A: Practice 4', NULL, 'Score from the front centre of the box and react quickly to changes of attacking direction.', 'Area split into 3 thirds plus 2 front-centre-of-box zones with a goal and GK at each end; 7v7 with a third team resting outside.', 'Teams attack; the final pass comes from outside the front-centre zone and the goal is scored from inside it. If no goal can be scored after receiving in the zone, play back out and the team in possession switches to attack the opposite goal.', 'Both teams can score in either goal but not twice in a row on the same goal. Games of 4-6 minutes, teams rotate, most goals over a set number of games wins.', NULL, 'Everyone reacts quickly to the transition when direction changes.', '7v7 + GKs, third team resting', 16, 23, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Attacking pattern, finish in back centre', 'combination', 'passive', 'in_possession', 96, 96, 'Session 8B: Practice 1', NULL, 'Rehearse a build-up pattern ending with a shot from the back centre of the box.', 'Half pitch with 4 mannequins as defenders and the back-centre-of-box zone highlighted; blues in positions CB, FB, M1 (floating), M2, F1, F2 and wingers, GK in goal.', 'CB plays wide to FB, who passes inside to M1; M1 to M2, M2 to F1, who lays off for M1 running forward; M1 passes across to F2, who drives into the back centre zone and shoots.', NULL, 'Alternative: M2 plays to the winger, who runs in behind and passes across for F1 to score. Repeat on the other side (M1 moves across); two groups can work in each half.', NULL, '8 blues + GK', 9, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 330),
  ('4-3-3 pattern, wide assists into back centre', 'combination', 'passive', 'in_possession', 97, 97, 'Session 8B: Practice 2', NULL, 'Rehearse combined 4-3-3 patterns that finish in the back centre of the box, with assists from wide players.', '10 blue outfielders in a 4-3-3 shape, mannequins as defenders at the edge of the box, back-centre zone highlighted, GK in goal.', 'CB plays wide to LCM, inside to DM, then to F. Three finishes: F lays off for LW driving inside into the zone to shoot; LW plays through for the overlapping LB to cut back for F; or F plays back to RCM, who sends RW through to assist.', NULL, 'Rotate or keep positions; repeat starting from the opposite side.', NULL, '10 blues + GK', 11, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('8v8+1 game, corner crossing zones', 'small_sided_game', 'overload', 'in_possession', 98, 98, 'Session 8B: Practice 3', NULL, 'Score from the back centre of the box, rewarding assists from the corner zones.', 'Half pitch with 2 corner zones reds may not enter, back-centre zone highlighted, full goal with GK, and 2 small goals on the halfway line for the reds.', 'Game starts with the deepest blue on the halfway line; blues build up in an 8v8 (+1 Joker) and try to score. Reds who win the ball counter to the 2 small goals.', 'Goals must be scored from inside the back-centre zone (ball may be passed or dribbled in); assists from a corner zone count double. Only 1 red may enter the box once the ball has been played there. After a save or ball out of play, restart from the deepest blue on halfway.', NULL, NULL, '8v8+1 + GK', 18, NULL, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 350),
  ('11v11, back-centre goals, corner zones', 'conditioned_game', 'opposed', 'in_possession', 99, 99, 'Session 8B: Practice 4', NULL, 'Finish from the back centre of the box in a full game, using corner zones for assists.', 'Full pitch 11v11 with 4 corner zones defenders may never enter; back-centre zones marked at both ends; no offside.', 'Coach''s pass starts it and the blues attack; reds attack the other way with the same aims.', 'Goals only from inside the back-centre zone; assists from a corner zone count double. After a save or ball out, restart from the red GK.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Play through lines and attack centre pattern', 'combination', 'unopposed', 'in_possession', 110, 110, 'Session 9A: Practice 1', NULL, 'Build up from the back by playing through the lines and attacking through the middle to finish.', 'Half pitch plus a bit with a GK in the big goal; mannequins (or cones) as defenders; two CBs, LCM, DM, RCM, forward and two wingers in position, balls with the CBs.', 'CB passes across to the other CB, who plays into the LCM; LCM sets back to the DM, who plays up to the forward; forward lays off to the RCM, who carries forward and returns it to the forward. The forward slips a through ball for either winger to run onto and shoot.', NULL, 'Raise the speed of execution; many alternative routes through the lines are possible.', 'Heads up to see positions and options; use mannequins rather than cones for realism.', '8 outfield + GK', 9, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Play through zones and in behind 5v3', 'phase_of_play', 'overload', 'in_possession', 111, 111, 'Session 9A: Practice 2', NULL, 'Progress through zones by passing or dribbling and then play in behind to finish.', 'Two zones in front of the box: first zone 5 blues v 3 reds, second zone 3+1 v 2 (forward, two wingers starting wide), GK in goal; waiting players outside.', 'Blues complete 3 passes in the first zone, then pass to the forward or a winger who moves into the second zone, or one player dribbles in. From the second zone they play a ball in behind into the box to score.', '3 passes before entering the next zone; reds stay in their zones; restart from a blue CB.', 'After a set number of reps the reds become the attackers; waiting players rotate in.', NULL, '5v3 + 3v2 + GK', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Attack through centre 5v5 with wide jokers', 'small_sided_game', 'opposed', 'in_possession', 112, 112, 'Session 9A: Practice 3', NULL, 'Attack through the centre and play in behind into the box to score.', 'Central zone in front of the big goal with yellow wide jokers in their own side zones; small counter goals at the other end; 4 teams of 5, GK in goal.', 'Short games: the blue team attacks through the centre, using the yellow wide players; after 3 passes they may play in behind for the forward or wingers to run into the box. When the phase ends the reds attack with the same aims.', '3 passes before playing in behind; defenders stay in the central zone; nobody else enters the wide zones; games 4-5 minutes, rotate teams and keep a total score.', NULL, NULL, '5v5 (+2) + GKs, 4 teams of 5', 20, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Five passes then attack either goal', 'small_sided_game', 'overload', 'in_possession', 113, 113, 'Session 9A: Practice 4', NULL, 'Keep the ball centrally then attack through the centre in a two-way game.', 'Central zone between two goals with GKs; 4 yellow jokers in outside zones; a blue forward and a red defender in the end zone.', 'Coach plays into the central zone; the team in possession needs 5 passes with joker help (5v5+4), then may attack either goal, with two jokers able to make forward runs. Pass in behind to the forward or runners to combine and score.', 'Minimum 5 passes; attack ends on goal, save or ball out, then Coach restarts to the other team.', NULL, NULL, '5v5 +4 jokers + GKs', 16, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Wide one-two, overlap, cross and finish', 'finishing', 'unopposed', 'in_possession', 115, 115, 'Session 9B: Practice 1', NULL, 'Quick combination out wide ending in a cross for runners in the box.', 'Half pitch with mannequins and a GK; players A, B, C, winger D, forward E and far winger D2 on cones, balls with A.', 'A passes into B, B sets to C who has moved off his cone; C plays wide to D. D plays a one-two with B, receives high on the flank and crosses near the byline while B, E and D2 attack the penalty spot, far and near post.', 'Rotate A to B to C to D to E to A.', 'Vary the type of cross; repeat from the left with a new ball.', NULL, '6 + GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 410),
  ('Wide 2v1 combination and cross vs defenders', 'finishing', 'opposed', 'in_possession', 116, 116, 'Session 9B: Practice 2', NULL, 'Beat a defender out wide with a one-two and overlap, then finish against a defender in the box.', 'As Practice 1 but with a red defender in the wide zone and another red defending the box; spare reds wait behind the goal.', 'Same opening combination; the wide red tries to cut out D''s pass to B, then recovers to block the cross. B, E and D2 run into the box to score against the red box defender.', 'Rotate A to B to C to D to E to A; restart from the left side.', 'Rotate defenders often; switch attacking and defending roles.', NULL, '6 + 2 defenders + GK', 9, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Multi-zone 6v6 crossing game', 'small_sided_game', 'opposed', 'in_possession', 117, 117, 'Session 9B: Practice 3', NULL, 'Move the ball wide and cross to finish in the box.', 'Half pitch split into 5 zones: central 4v4+1, two wide channels 1v1, and the box; GKs at both ends; a yellow joker for the team in possession; a third team rests outside.', 'GK plays into the central zone; the ball must go into a wide zone then into the box; 2 attackers plus the joker can enter the box to make a 3v2.', 'Only 2 from each team plus the joker enter the box; games 3-5 minutes; after a goal the conceding team''s GK restarts; teams rotate.', NULL, NULL, '6v6 (+1) + GKs, 3 teams', 21, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Multi-zone 8v8 crossing game', 'small_sided_game', 'opposed', 'in_possession', 118, 118, 'Session 9B: Practice 4', NULL, 'Create 2v1s on the flank and cross into the box in a bigger game.', 'Larger area with central zone, two wide channels and box; 8v8 plus 2 rotating jokers outside, GKs.', 'Ball goes from the centre into a wide zone and then into the box; in the wide zone a joker can join to make a 2v1 (e.g. overlap and cross). Three per team plus the joker can enter the box (4v3).', 'Only 3 per team plus joker in the box; conceding team''s GK restarts after a goal.', NULL, NULL, '8v8 (+2) + GKs', 20, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Long pass, switch, cut back and finish', 'combination', 'unopposed', 'in_possession', 120, 120, 'Session 9C: Practice 1', NULL, 'Practise long passes and switches of play ending in a cut back and shot.', 'Full pitch length; 4 deep cones (A1-A4) with balls in own half, receivers B1 and B2 wide in the final third, C1/C2 near the box, forward D, GK.', 'A plays a long pass to B1 or B2, who controls and switches to the other B moving off his cone; that B switches again to C1 coming into the box, who cuts back for D to finish.', 'Each repetition starts from the next A cone to vary angles.', 'Rotate roles after a set number of reps.', NULL, 'about 10 + GK', 9, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Long pass into zone then combine to finish', 'combination', 'passive', 'in_possession', 121, 121, 'Session 9C: Practice 2', NULL, 'Hit a long pass into the final third and combine quickly to score.', 'Deep passers at positions A and B (B1, B2); receiving zone before the box with E1, E2; wide players C1, C2 and runners D1, D2; mannequins and GK.', 'Long pass left, right or centre. Wide: C either passes for D''s run to the byline for a cut back, or crosses for forward E. Central: E1 and E2 combine with C1 or C2 (e.g. through ball for C1).', NULL, 'Rotate C and D with resting players; rotate roles after a set number.', NULL, 'about 10 + GK', 11, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Long passes into 2v1 zones 6v3', 'phase_of_play', 'overload', 'in_possession', 122, 122, 'Session 9C: Practice 3', NULL, 'Win second balls from long passes and exploit 2v1s to score.', 'Three zones across the final third, each 2 blues v 1 red; deep passers at cones A, B, C; GK.', 'Long pass into any zone. Wide: the two blues attack the flank or switch, then cross for the central pair. Central: the pair combine to score through the middle.', 'Restart from the next cone even if reds win it; rotate red defenders every 1-2 reps.', NULL, NULL, '6v3 + GK + passers', 13, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 470),
  ('11v11 zone switching 2v1 game', 'conditioned_game', 'opposed', 'in_possession', 123, 123, 'Session 9C: Practice 4', NULL, 'Switch play between zones to create 2v1s and score from the second ball.', 'Full pitch 11v11 with four corner zones marked (two in each half); max 2 attackers and 1 defender per zone.', 'GK starts; the team in possession must complete 2 long passes or switches from zone to zone before it can score. Reds who win it need 2 zone-to-zone passes too.', 'Max 2 attackers + 1 defender in any zone; game refreshes after ball out or a save, needing 2 zone passes again.', NULL, NULL, '11v11', 22, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Combination around box on GO call', 'combination', 'unopposed', 'in_possession', 128, 128, 'Session 10A: Practice 1', NULL, 'Fast, precise combination play around the box and a timely assist in behind.', 'Players in positions around the edge of the box with 4 mannequins, GK; two groups can work in each half.', 'Starting left or right, players pass freely forward, back or sideways at speed; when the Coach shouts GO the player on the ball must pass into the box for a teammate''s run to finish.', NULL, 'Rotate positions and restart from the other side.', 'Speed and precision of combinations.', 'about 8 + GK', 9, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Edge of box 6v3 through-pass practice', 'phase_of_play', 'overload', 'in_possession', 129, 129, 'Session 10A: Practice 2', NULL, 'Combine and time a pass in behind the back line at the edge of the box.', 'Zone A in front of the box, Zone B a strip at the edge (3v3), Zone C the box; outside blue players feed in; GK.', 'An outside player passes into Zone A; blues need 3 passes, then a through pass into Zone C as Zone B attackers run in. The receiver shoots or squares for a teammate.', '3 passes in Zone A; red defenders slide horizontally and cannot enter Zone C.', 'Rotate: passer into Zone A, through-passer into Zone C, shooter to start.', NULL, '6v3 + GK', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('4v4 three-zone centre combination game', 'phase_of_play', 'opposed', 'in_possession', 130, 130, 'Session 10A: Practice 3', NULL, 'Attack through the centre with a through pass while defenders can counter.', 'Zone A 2(+1)v2 with yellow joker, Zone B 2v2 at the box edge, Zone C the box; big goal with GK, 2 small goals for reds to counter.', 'Blues need 3 passes in Zone A then a through pass into Zone C for Zone B runners. Reds win it and counter into the small goals. Restart from the joker.', '3 passes before the through pass.', 'Switch roles; run a league or semi-final/final with two groups.', NULL, '4v4 (+1) + GK', 10, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 510),
  ('8v8 five-zone receive-and-score game', 'small_sided_game', 'overload', 'in_possession', 131, 131, 'Session 10A: Practice 4', NULL, 'Find a player in the red receiving zone who then makes a decisive individual action to score.', 'Two goals with GKs; central zone, red receiving strips near each box, end zones; 8v8 plus 2 jokers.', 'Coach starts; the team in possession can attack either goal. A pass must be received in a red zone; that player must score alone or pass back to the centre and the team may switch direction.', 'No offside; defenders cannot enter the end zones; restart from the Coach to the defending team.', NULL, NULL, '8v8 (+2) + GKs', 20, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Wide give-and-go, cross or cut back', 'finishing', 'unopposed', 'in_possession', 133, 133, 'Session 10B: Practice 1', NULL, 'Attack down the flank with a give and go, then cross or cut back to score.', 'Players on cones with 4 mannequins on each side, GK; two groups can use either half.', 'A plays diagonally to B, who sets wide to C. C either plays a give and go with D and goes up the flank, or passes into the box for forward E. Finish with an aerial cross to E at the back post or a low cross/cut back for B or D.', NULL, 'Rotate positions; repeat from the left side.', NULL, '5 + GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 530),
  ('4v3 wide combination with red goal zone', 'phase_of_play', 'overload', 'in_possession', 134, 134, 'Session 10B: Practice 2', NULL, 'Combine down one flank to score while defending a counter.', 'Area from the box out past halfway with a ''Goal Zone'' for reds; 4 blues v 3 reds + GK; resting players outside.', 'Coach starts; blues attack down the right flank in a 4v3. If reds win it they score by receiving a pass inside the Goal Zone.', 'Goals count only if the attack comes down the right flank.', 'Halfway through, move cones and attack down the left side.', NULL, '4v3 + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 540),
  ('6v6 vertical split-zone wide game', 'small_sided_game', 'opposed', 'in_possession', 135, 135, 'Session 10B: Practice 3', NULL, 'Use combination play down one side to get in behind and into the box.', 'Half pitch with 2 goals and GKs; two central zones split down the middle, 3v3 in each half plus 1 joker who can cross both.', 'GK plays into a central zone; blues attack down that side with combinations, then a through pass or dribble in behind. Once in behind, players from both zones can enter the box. Reds counter if they win it.', '3+ passes within the zone before passing or dribbling forward.', 'Restart from the reds'' GK with roles reversed.', NULL, '6v6 (+1) + GKs', 15, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('11v11 multi-zone wide combination game', 'conditioned_game', 'opposed', 'in_possession', 136, 136, 'Session 10B: Practice 4', NULL, 'Score via combination play through the high wide zones.', 'Full pitch, blues 4-3-3 v reds 4-4-2 (adjustable); 2 low wide zones and 2 high wide zones marked.', 'GK starts and blues build up; to score the ball must go through a high wide zone, then players run into the box. Reds counter if they win it.', 'Low zones: max 2 blues + 1 red; high zones: max 3 blues + 2 reds.', 'Restart from the reds'' GK with roles reversed.', NULL, '11v11', 22, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Defend free kick, fast 3v2 counter', 'transition', 'opposed', 'to_attack', 142, 142, 'Session 11A: Practice 1', NULL, 'Clear a wide free kick and launch a quick counter attack.', 'Full pitch; red wide free kick taker, 2 red attackers v 3 blue defenders + GK in the box; 2 blue midfielders and a forward ahead; 2 red defenders on the far line; resting players outside.', 'When blues clear or the GK catches, the counter starts; only then the 2 midfielders and forward break for a 3v2 against the 2 red defenders.', 'Attacking trio only moves once the ball leaves the box; the 2 red defenders stay on their line until the ball is played.', 'Defenders become midfielders/forward, rotate with resting players; restart from the other side.', NULL, '3v2 + 3v2 + GKs', 13, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('4(+1)v3 win ball and counter', 'transition', 'overload', 'to_attack', 143, 143, 'Session 11A: Practice 2', NULL, 'Win the ball near your box and counter quickly via the forward.', 'Full pitch; reds attack a ''1 Goal Zone'' at the edge of the blue box; 4 blues defend, blue forward up the pitch; goals at both ends.', 'Reds 3v4 try to receive a pass in the 1 Goal Zone (1 point) and then score (2). Blues push out to win it and counter, passing to the forward first, all four joining while 3 reds sprint back.', 'Forward must play to a teammate before the blues can score.', 'New group of 4 blues and 3 reds each phase; swap roles at halfway and make it a competition.', NULL, '4 (+1) v 3 + GKs', 10, NULL, 'full pitch', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Two-zone 8v6 win and counter', 'transition', 'overload', 'to_attack', 144, 144, 'Session 11A: Practice 3', NULL, 'Win the ball in the defensive half and counter with a 3v2.', 'Reduced-width area split at halfway; reds 4v5 +GK attack in one half; 3 blue attackers v 2 red defenders wait near halfway in the other.', 'Coach passes to the reds, who try to score. Blues win it and pass forward to an attacker, who then finishes with the 3v2.', 'After each phase change the 3 blue forwards and 2 red defenders.', 'Coach restarts with a new ball to the 4 reds.', NULL, '8v6 + GKs', 16, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 590),
  ('7v7(+2) win in own half and counter', 'transition', 'overload', 'to_attack', 145, 145, 'Session 11A: Practice 4', NULL, 'Get more ball wins in the defensive half and finish counters 3v3.', 'Pitch split into 2 halves; reds attack 7v7 +GK; 2 extra blue defenders run in to make +2; goals at both ends.', 'Reds try to score; blues win it and pass into the attacking half; the receiver tries to score with 2 teammates while 3 reds recover (3v3).', '2 blue defenders leave after the win (can be different each time); all goals count 1.', 'Coach restarts to the reds at the other end with roles reversed.', NULL, '7v7 (+2) + GKs', 18, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('3v1 high press and fast counter', 'transition', 'overload', 'to_attack', 147, 147, 'Session 11B: Practice 1', NULL, 'Press high, steal the ball and score quickly.', 'A box-sized zone at the top of the attacking half plus a ''Goal Zone'' for the red player behind it; 3 blues, red feeders outside with balls, GK.', 'Outside red passes to a red near the arc who tries to dribble into the Goal Zone. The 3 blues press together to win it and counter to score.', 'No offside.', 'Rotate with resting players; restart from the left.', NULL, '3v1 + GK', 5, NULL, 'zone the size of the box', NULL, NULL, NULL, true, true, true, NULL, 610),
  ('4v2 high press and fast counter', 'transition', 'overload', 'to_attack', 148, 148, 'Session 11B: Practice 2', NULL, 'Press two opponents high and counter quickly after winning it.', 'Larger area than Practice 1 with a Goal Zone for reds; 4 blues v 2 reds, red feeders outside, GK.', 'Outside red passes in; reds try to dribble into or receive in the Goal Zone. The 4 blues press together, win it and counter to score.', 'No offside.', 'Rotate with resting players; restart from the left.', NULL, '4v2 + GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 620),
  ('5v5 high press from goal kick', 'transition', 'opposed', 'to_attack', 149, 149, 'Session 11B: Practice 3', NULL, 'Press a short goal kick high and score fast after the steal.', 'Full half pitch, a wide Goal Zone across the halfway end for reds; 5v5, GK.', 'Short goal kick to a red in the box; reds aim to dribble into or receive in the Goal Zone. Once the ball leaves the box the 3 reds starting in the Goal Zone can come out. Blues press, win it and counter.', 'No offside; restart with a new goal kick.', 'Swap roles halfway and see which team scores more.', NULL, '5v5 + GK', 11, NULL, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 630),
  ('Two-zone 6v5 high press transition game', 'transition', 'overload', 'to_attack', 150, 150, 'Session 11B: Practice 4', NULL, 'Win the ball high in the opponent''s half and finish quickly.', 'Pitch in two halves with goals at both ends; reds build from a goal kick, blues press 6v5 (+GK) in that half.', 'Reds must complete 3 passes before playing into the other half; blues press to win it in the low half and score quickly. If reds get through, it becomes a normal game towards the far goal.', 'Reds need at least 3 passes before advancing.', 'Restart with a goal kick and roles reversed.', NULL, '6v5 + GKs (11v11 shown)', 13, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 640),
  ('Winger 1v1 then cut back for runners', 'finishing', 'opposed', 'in_possession', 153, 153, 'Combined Training Session: Practice 1', NULL, 'Beat a defender 1v1 in the corner and cut back for oncoming runners.', 'Corner areas marked at both sides of the box with a mannequin; red defender D, midfielder M, winger W and forward F, GK; players wait on both sides.', 'Coach passes to M, who plays wide ahead of W. D runs round the mannequin into the corner area; W takes him on 1v1 and cuts back for F or M arriving at near and far post.', NULL, 'Players return or rotate; next group goes from the other side.', NULL, '3v1 + GK', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Wing play into side of box 2v2', 'finishing', 'opposed', 'in_possession', 154, 154, 'Combined Training Session: Practice 2', NULL, 'Combine down the wing into the side of the box and cut back to finish.', 'Side-of-box zones marked; RB, M1, M2, winger W and forward F v 2 red defenders in the box, mannequins, GK.', 'RB passes to M1, M1 to M2, who plays wide for RB''s forward run. RB plays W in behind or a short pass for W to dribble past the mannequin into the side of the box; W cuts back or crosses low for M2 or F as reds try to block.', NULL, 'Repeat from the left with 2 new defenders; rotate positions throughout.', NULL, '5 + 2 defenders + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 660)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coach-your-team-to-score-more-goals-data-driven-analysis-of-europe-s-elite-used-') b;
INSERT INTO schema_migrations (filename) VALUES ('2405-exercises-book-coach-your-team-to-score-more-goals-data-driven-analysis-of-.sql') ON CONFLICT DO NOTHING;
COMMIT;
